0934331f-68aa-48ab-8f48-4ff432a5106b	2026-09-06 11:54:08.917375+00	2026-09-06 11:54:08.917397+00	Cahier des charges technique — Spécifications pour la livraison des assets	1.0	Le présent cahier des charges définit les spécifications techniques et\néditoriales applicables à la livraison des contenus sur EKEFLICKS.\n\nIl vise à garantir la qualité, l'interopérabilité et la conformité des\nassets remis par les producteurs, studios, distributeurs et ayants droit.\n\nLes exigences applicables peuvent dépendre du type de contenu, du meilleur\nmaster disponible, du contrat conclu avec EKEFLICKS et du niveau de\nlivraison retenu : Premium, Standard ou Distribution.	[{"key": "principles", "items": [{"label": "Niveaux de livraison", "value": "EKEFLICKS accepte trois niveaux : Master Premium, Master Standard et Master Distribution."}, {"label": "HDR", "value": "Le HDR n'est obligatoire que lorsqu'un master HDR est livré ou spécifiquement demandé."}, {"label": "Audio multicanal", "value": "5.1 ou 7.1 si disponible. Une piste stéréo conforme reste acceptée lorsque le master ne comporte pas de multicanal."}, {"label": "Sous-titres et doublages", "value": "Les sous-titres multilingues et pistes de doublage sont livrés lorsqu'ils existent ou sont contractuellement requis."}, {"label": "Validation", "value": "EKEFLICKS peut effectuer des contrôles automatiques et manuels avant validation définitive."}], "title": "1. Principes généraux de livraison", "description": "Les fichiers livrés doivent correspondre au meilleur master professionnel disponible. Les brouillons peuvent être incomplets, mais la soumission finale doit respecter les exigences applicables."}, {"key": "poster", "items": [{"label": "Ratio", "value": "2:3 exact.", "required": true, "rule_key": "poster.aspect_ratio", "auto_validation": true}, {"label": "Résolution minimale", "value": "1000 × 1500 pixels.", "required": true, "rule_key": "poster.min_resolution", "auto_validation": true}, {"label": "Résolution recommandée", "value": "3000 × 4500 pixels."}, {"label": "Poids maximal", "value": "20 Mo.", "required": true, "rule_key": "poster.max_size_mb", "auto_validation": true}, {"label": "Formats", "value": "PNG ou JPG/JPEG en qualité maximale.", "required": true, "rule_key": "poster.formats", "auto_validation": true}, {"label": "Espace colorimétrique", "value": "RGB."}, {"label": "Titre", "value": "Le titre localisé de l'œuvre peut apparaître."}, {"label": "Éléments interdits", "value": "Bordures, logos DVD/Blu-ray, logos de plateformes concurrentes, texte promotionnel ou dates de sortie."}, {"label": "Zone de sécurité", "value": "Conserver les informations essentielles dans une zone de sécurité d'environ 10 % autour des bords."}], "title": "2. Poster", "description": "Affiche principale verticale utilisée dans le catalogue EKEFLICKS."}, {"key": "banner", "items": [{"label": "Ratio", "value": "16:9 exact.", "required": true, "rule_key": "banner.aspect_ratio", "auto_validation": true}, {"label": "Résolution minimale", "value": "1920 × 1080 pixels.", "required": true, "rule_key": "banner.min_resolution", "auto_validation": true}, {"label": "Résolution recommandée", "value": "3840 × 2160 pixels."}, {"label": "Poids maximal", "value": "10 Mo.", "required": true, "rule_key": "banner.max_size_mb", "auto_validation": true}, {"label": "Formats", "value": "PNG ou JPG/JPEG.", "required": true, "rule_key": "banner.formats", "auto_validation": true}, {"label": "Espace colorimétrique", "value": "RGB."}, {"label": "Texte", "value": "Éviter les textes localisés intégrés au visuel, sauf validation éditoriale spécifique."}, {"label": "Éléments interdits", "value": "Logos de plateformes concurrentes."}, {"label": "Composition", "value": "Les personnages, visages et éléments clés doivent rester dans la zone centrale de sécurité."}], "title": "3. Bannière", "description": "Visuel horizontal principal utilisé dans les interfaces éditoriales EKEFLICKS."}, {"key": "trailer", "items": [{"label": "Master recommandé", "value": "MOV Apple ProRes 422 ou ProRes 422 HQ. Une livraison MP4 professionnelle peut être acceptée pour le niveau Distribution."}, {"label": "Résolution recommandée", "value": "3840 × 2160 lorsque disponible."}, {"label": "Résolution minimale", "value": "1920 × 1080, sauf source historique ou exception préalablement approuvée."}, {"label": "Aspect ratio", "value": "Respect du ratio natif de la source."}, {"label": "Framerate", "value": "Constant : 23.976, 24, 25, 29.97 ou 30 fps.", "required": true, "rule_key": "trailer.allowed_fps", "auto_validation": true}, {"label": "Audio", "value": "PCM 48 kHz recommandé pour les masters ProRes. AAC 48 kHz haute qualité accepté pour MP4."}, {"label": "Sous-titres", "value": "SRT ou WebVTT livrés séparément si disponibles."}, {"label": "HDR", "value": "Rec.2020 ou DCI-P3 selon le master. Métadonnées HDR ou Dolby Vision fournies en sidecar lorsque nécessaires."}, {"label": "Durée", "value": "30 secondes à 2 minutes 30.", "required": true, "rule_key": "trailer.duration", "auto_validation": true}, {"label": "Convention de nommage", "value": "[Titre]_S[XX]_Trailer_[Type]_[Res]_[HDR].ext pour une série ; adaptation équivalente pour un film."}], "title": "4. Bande-annonce", "description": "La meilleure source professionnelle disponible doit être livrée."}, {"key": "master_levels", "items": [{"label": "Master Premium", "value": "Destiné notamment aux Originals, studios, contenus premium et workflows HDR. MOV Apple ProRes 422 HQ, ProRes 4444 ou ProRes 4444 XQ selon le master disponible. UHD ou résolution native. 10 ou 12 bits selon le codec et la source."}, {"label": "Master Standard", "value": "Destiné aux producteurs professionnels. MOV Apple ProRes 422 ou 422 HQ, UHD ou Full HD, vidéo progressive, PCM 48 kHz / 24 bits recommandé."}, {"label": "Master Distribution", "value": "Destiné notamment aux producteurs indépendants lorsque le ProRes n'est pas disponible. MP4 H.264 AVC ou H.265/HEVC haute qualité, Full HD ou 4K."}], "title": "5. Niveaux de livraison du master programme", "description": "Le niveau applicable dépend du contrat, de l'origine du contenu et du meilleur master professionnel disponible."}, {"key": "program_video", "items": [{"label": "Conteneur Premium / Standard", "value": "MOV."}, {"label": "Codecs Premium", "value": "Apple ProRes 422 HQ, 4444 ou 4444 XQ selon le master disponible."}, {"label": "Codecs Standard", "value": "Apple ProRes 422 ou 422 HQ."}, {"label": "Distribution", "value": "MP4 H.264 AVC ou H.265/HEVC."}, {"label": "H.264 dans MOV", "value": "Non accepté comme livraison Distribution. Une source H.264 doit être encapsulée en MP4.", "required": true, "rule_key": "master.h264_container", "auto_validation": true}, {"label": "Résolution", "value": "Full HD 1920 × 1080 minimum recommandé ; 3840 × 2160 pour UHD/4K lorsque disponible."}, {"label": "Aspect ratio", "value": "Respect du ratio natif de l'œuvre."}, {"label": "Framerate", "value": "Constant : 23.976, 24, 25, 29.97 ou 30 fps.", "required": true, "rule_key": "master.allowed_fps", "auto_validation": true}, {"label": "Scan", "value": "Progressif uniquement.", "required": true, "rule_key": "master.progressive", "auto_validation": true}, {"label": "Débit Distribution", "value": "Au moins 30 Mb/s recommandé en Full HD et 50 Mb/s recommandé en 4K."}, {"label": "Intervalle image clé", "value": "Maximum 2 secondes pour H.264/H.265 Distribution."}, {"label": "SDR", "value": "Rec.709 accepté et recommandé pour les masters SDR."}, {"label": "HDR", "value": "Rec.2020 ou espace approprié au master HDR ; P3 peut être utilisé dans les workflows adaptés."}, {"label": "Audio Premium / Standard", "value": "PCM 48 kHz / 24 bits recommandé. Stéréo, 5.1 ou 7.1 selon le meilleur master disponible."}, {"label": "Audio Distribution", "value": "AAC 48 kHz haute qualité, 256 kb/s ou supérieur recommandé, ou PCM lorsque disponible."}, {"label": "Sous-titres", "value": "Fichiers SRT ou WebVTT séparés."}, {"label": "Doublages", "value": "Pistes audio séparées lorsqu'elles existent."}, {"label": "HDR sidecar", "value": "Métadonnées XML Dolby Vision, HDR10+ ou autres fichiers sidecar fournis lorsque le format l'exige."}], "title": "6. Vidéo programme — exigences techniques", "description": "Les spécifications ci-dessous sont contrôlées selon le niveau de livraison applicable."}, {"key": "naming", "items": [{"label": "Épisode", "value": "[TitreSerie]_S[XX]_E[XX]_[TitreEpisode]_[Res]_[HDR].ext"}, {"label": "Trailer série", "value": "[TitreSerie]_S[XX]_Trailer_[Type]_[Res]_[HDR].ext"}, {"label": "Film", "value": "[TitreFilm]_[Type]_[Res]_[HDR].ext"}, {"label": "Règles", "value": "Éviter les caractères spéciaux incompatibles avec les systèmes de fichiers et conserver une convention cohérente."}], "title": "7. Convention de nommage", "description": "Les noms de fichiers doivent permettre l'identification immédiate du contenu livré."}, {"key": "metadata", "items": [{"field": "title", "label": "Titre", "value": "Obligatoire.", "required": true}, {"field": "original_title", "label": "Titre original", "value": "Obligatoire.", "required": true}, {"field": "season_episode", "label": "Saison / épisode", "value": "Obligatoire pour les séries et épisodes.", "required": true, "conditional": "series"}, {"field": "synopsis", "label": "Synopsis court", "value": "150 à 300 caractères.", "required": true}, {"field": "long_synopsis", "label": "Synopsis long", "value": "500 à 1000 caractères recommandé.", "required": false}, {"field": "genres", "label": "Genres", "value": "Obligatoire.", "required": true}, {"field": "production_year", "label": "Année de production", "value": "Obligatoire.", "required": true}, {"field": "directors", "label": "Réalisateur(s)", "value": "Obligatoire.", "required": true}, {"field": "cast", "label": "Acteurs principaux", "value": "Obligatoire, dans l'ordre d'importance.", "required": true}, {"field": "screenwriters", "label": "Scénariste(s)", "value": "Obligatoire.", "required": true}, {"field": "producers", "label": "Producteur(s)", "value": "Obligatoire.", "required": true}, {"field": "age_rating", "label": "Classification", "value": "Obligatoire. Exemple : Tous publics, 12+, 16+, 18+.", "required": true}, {"field": "duration", "label": "Durée exacte", "value": "Obligatoire, en minutes.", "required": true}, {"field": "original_language", "label": "Langue originale", "value": "Obligatoire.", "required": true}, {"field": "audio_languages", "label": "Langues audio", "value": "Obligatoire.", "required": true}, {"field": "subtitle_languages", "label": "Langues de sous-titres", "value": "Obligatoire comme déclaration ; indiquer Aucun si aucune piste n'est disponible.", "required": true}, {"field": "platform_release_date", "label": "Date de mise en ligne prévue", "value": "Obligatoire.", "required": true}, {"field": "country_of_origin", "label": "Pays d'origine", "value": "Obligatoire.", "required": true}], "title": "8. Métadonnées obligatoires", "description": "Les métadonnées doivent être complètes avant la soumission finale."}, {"key": "xml", "items": [{"label": "Fonction", "value": "L'XML préremplit uniquement les champs reconnus."}, {"label": "Validation", "value": "L'import XML ne soumet jamais automatiquement un contenu."}, {"label": "Contrôle producteur", "value": "Les valeurs importées sont affichées au producteur pour vérification et correction avant enregistrement."}, {"label": "Schéma", "value": "Format EKEFLICKS Metadata XML versionné. Un modèle XML téléchargeable sera fourni."}, {"label": "Séries", "value": "Le schéma pourra contenir les saisons et épisodes avec leurs métadonnées propres."}], "title": "9. Import XML des métadonnées", "description": "EKEFLICKS pourra accepter un fichier XML pour préremplir le formulaire de dépôt."}, {"key": "deadlines", "items": [{"label": "Poster", "value": "J-30 minimum."}, {"label": "Bannière", "value": "J-30 minimum."}, {"label": "Master programme", "value": "J-30 minimum."}, {"label": "Métadonnées", "value": "J-30 minimum."}, {"label": "Trailer", "value": "J-14 minimum."}, {"label": "Exceptions", "value": "Toute exception doit faire l'objet d'un accord écrit préalable d'EKEFLICKS."}], "title": "10. Délais de livraison", "description": "Les délais sont calculés avant la date de mise en ligne prévue."}, {"key": "conformity", "items": [{"label": "Poster", "value": "Contrôle possible du format, ratio, dimensions et poids."}, {"label": "Bannière", "value": "Contrôle possible du format, ratio, dimensions et poids."}, {"label": "Vidéo", "value": "Contrôle serveur prévu via FFprobe : conteneur, codec, résolution, framerate, scan, débit, audio et autres caractéristiques techniques disponibles."}, {"label": "Métadonnées", "value": "Contrôle des champs obligatoires avant soumission finale."}, {"label": "Rapport", "value": "Le producteur pourra visualiser un rapport de conformité et les éléments à corriger."}], "title": "11. Contrôle de conformité EKEFLICKS", "description": "Les livraisons peuvent être analysées automatiquement après upload."}]	f	2026-09-06 11:54:08.912868+00
